<script setup lang="ts">
import { createClient, type SupabaseClient, type Session } from '@supabase/supabase-js'
import { liveQuery } from 'dexie'
import { db,saveRecord,synchronize,removeAccountCache,resolveConflict } from './lib/store'
import { createStarter } from './lib/sample'
import { snapshotSession,type LocalRecord,type Kind,type Exercise,type Workout,type TrainingSession,type Payload } from '../shared/domain'
const cfg=useRuntimeConfig(),auth=shallowRef<SupabaseClient|null>(null),authSession=ref<Session|null>(null),recovery=ref(false),ready=ref(false),local=ref(false)
const owner=computed(()=>authSession.value?.user.id||(local.value?'local-device':'')),displayName=computed(()=>authSession.value?.user.user_metadata?.display_name||'Atleta')
const rows=ref<LocalRecord[]>([]),pending=ref(0),view=ref('oggi'),search=ref(''),status=ref('Salvato sul dispositivo'),online=ref(true),busy=ref(false),toast=ref(''),cycleId=ref(''),planId=ref(''),workoutId=ref(''),sessionRecord=ref<LocalRecord|null>(null),focusMode=ref(false)
const editor=reactive<{open:boolean;kind:Kind;record?:LocalRecord;parentId?:string}>({open:false,kind:'exercise'}),deleteRecord=ref<LocalRecord|null>(null),logoutOpen=ref(false),historyRecord=ref<LocalRecord|null>(null),videoUrl=ref(''),conflictRecord=ref<LocalRecord|null>(null)
const catalog=computed(()=>rows.value.filter(r=>r.kind==='exercise'&&!r.deleted)),cycles=computed(()=>rows.value.filter(r=>r.kind==='cycle'&&!r.deleted)),cycle=computed(()=>cycles.value.find(r=>r.id===cycleId.value)||cycles.value[0]),plans=computed(()=>rows.value.filter(r=>r.kind==='plan'&&r.parent_id===cycle.value?.id&&!r.deleted).sort((a,b)=>(a.payload as any).order-(b.payload as any).order)),plan=computed(()=>plans.value.find(r=>r.id===planId.value)||plans.value[0]),workouts=computed(()=>rows.value.filter(r=>r.kind==='workout'&&r.parent_id===plan.value?.id&&!r.deleted).sort((a,b)=>(a.payload as Workout).order-(b.payload as Workout).order)),workout=computed(()=>workouts.value.find(r=>r.id===workoutId.value)||workouts.value[0]),workoutData=computed(()=>workout.value?.payload as Workout|undefined)
const sessions=computed(()=>rows.value.filter(r=>r.kind==='session'&&!r.deleted).sort((a,b)=>(b.payload as TrainingSession).startedAt.localeCompare((a.payload as TrainingSession).startedAt))),completed=computed(()=>sessions.value.filter(r=>(r.payload as TrainingSession).completedAt)),ongoing=computed(()=>sessions.value.find(r=>!(r.payload as TrainingSession).completedAt)),weights=computed(()=>rows.value.filter(r=>r.kind==='weight'&&!r.deleted).sort((a,b)=>(a.payload as any).measuredAt.localeCompare((b.payload as any).measuredAt))),latestWeight=computed(()=>weights.value.at(-1)?.payload as {kg:number;measuredAt:string}|undefined),conflicts=computed(()=>rows.value.filter(r=>r.conflict)),filteredCatalog=computed(()=>catalog.value.filter(r=>(r.payload as Exercise).name.toLowerCase().includes(search.value.toLowerCase())))
const modeNames:Record<string,string>={bodyweight:'Corpo libero',weighted:'Zavorra',external:'Carico esterno',band:'Banda elastica'}
const week=computed(()=>cycle.value?Math.max(1,Math.min((cycle.value.payload as any).weeks,Math.floor((Date.now()-new Date((cycle.value.payload as any).start).getTime())/604800000)+1)):1)
const monday=()=>{const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-(d.getDay()+6)%7);return d}
const weekly=computed(()=>completed.value.filter(r=>new Date((r.payload as TrainingSession).completedAt!)>=monday()))
const activity=computed(()=>Array.from({length:7},(_,i)=>weekly.value.some(r=>(new Date((r.payload as TrainingSession).completedAt!).getDay()+6)%7===i)))
const graph=computed(()=>{const values=weights.value.slice(-14).map(r=>(r.payload as any).kg as number);if(values.length<2)return '';const min=Math.min(...values)-.2,range=Math.max(...values)-min+.2;return values.map((n,i)=>`${i?'L':'M'}${i/(values.length-1)*280},${68-(n-min)/range*60}`).join(' ')})
let unsubscribe:(()=>void)|undefined,authSubscription:{unsubscribe:()=>void}|undefined,interval:ReturnType<typeof setInterval>|undefined,toastTimer:ReturnType<typeof setTimeout>,syncing=false
function notify(message:string){toast.value=message;void nextTick(()=>{const node=document.getElementById('toast') as HTMLElement|null;if(node?.showPopover&&!node.matches(':popover-open'))node.showPopover()});clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',5000)}
async function sync(){if(syncing||!owner.value)return;if(local.value){status.value='Solo dispositivo';return}const id=owner.value;syncing=true;try{await synchronize(id,async()=>{const {data}=await auth.value!.auth.getSession();return data.session?.user.id===id?data.session.access_token:null},s=>{if(owner.value===id)status.value=s})}finally{syncing=false}}
async function observeOwner(){unsubscribe?.();rows.value=[];pending.value=0;sessionRecord.value=null;focusMode.value=false;cycleId.value='';planId.value='';workoutId.value='';const id=owner.value;if(!id)return;const saved=(await db.meta.get(id+':selection'))?.value;if(owner.value!==id)return;if(saved){cycleId.value=saved.cycle||'';planId.value=saved.plan||'';workoutId.value=saved.workout||''}const sub=liveQuery(async()=>({records:await db.records.where('user_id').equals(id).toArray(),pending:await db.queue.where('owner').equals(id).count()})).subscribe({next:value=>{if(owner.value===id){rows.value=value.records;pending.value=value.pending}},error:()=>notify('Impossibile aprire l’archivio del dispositivo.')});unsubscribe=()=>sub.unsubscribe();void sync()}
watch(owner,observeOwner)
watch([cycleId,planId,workoutId],()=>{if(owner.value)void db.meta.put({key:owner.value+':selection',value:{cycle:cycleId.value,plan:planId.value,workout:workoutId.value}})})
function connectivity(){online.value=navigator.onLine;if(online.value)void sync();else status.value='Offline · salvato sul dispositivo'}
onMounted(async()=>{online.value=navigator.onLine;window.addEventListener('online',connectivity);window.addEventListener('offline',connectivity);if(cfg.public.supabaseUrl&&cfg.public.supabaseKey){auth.value=createClient(String(cfg.public.supabaseUrl),String(cfg.public.supabaseKey));const {data}=auth.value.auth.onAuthStateChange((event,session)=>{authSession.value=session;if(session)local.value=false;if(event==='PASSWORD_RECOVERY')recovery.value=true});authSubscription=data.subscription;const session=await auth.value.auth.getSession();authSession.value=session.data.session}local.value=Boolean(cfg.public.allowLocalDemo)&&!authSession.value&&localStorage.getItem('gymbrain-local')==='yes';ready.value=true;interval=setInterval(()=>void sync(),30000)})
onUnmounted(()=>{unsubscribe?.();authSubscription?.unsubscribe();clearInterval(interval);clearTimeout(toastTimer);window.removeEventListener('online',connectivity);window.removeEventListener('offline',connectivity)})
function enterLocal(){if(!cfg.public.allowLocalDemo)return;localStorage.setItem('gymbrain-local','yes');local.value=true}
function openEditor(kind:Kind,record?:LocalRecord,parentId?:string){Object.assign(editor,{open:true,kind,record,parentId})}
async function save(kind:Kind,payload:Payload,id?:string,parentId?:string|null,expectedRevision?:number){try{await saveRecord(owner.value,kind,payload,{id,parentId,expectedRevision});editor.open=false;notify('Salvato sul dispositivo');void sync()}catch(e){notify(e instanceof Error?e.message:'Salvataggio non riuscito')}}
async function seed(){busy.value=true;try{const result=await createStarter(owner.value);cycleId.value=result.cycle;planId.value=result.plan;notify('Percorso iniziale creato: puoi personalizzarlo.');void sync()}catch(e){notify(String(e))}finally{busy.value=false}}
async function start(){try{if(ongoing.value){sessionRecord.value=ongoing.value;focusMode.value=true;return}if(!workout.value||!workoutData.value?.exercises.length){notify('Aggiungi almeno un esercizio alla giornata.');return}sessionRecord.value=await saveRecord(owner.value,'session',snapshotSession(workout.value,latestWeight.value?.kg??null));focusMode.value=true}catch(e){notify(String(e))}}
async function sessionComplete(){focusMode.value=false;const i=workouts.value.findIndex(w=>w.id===(sessionRecord.value!.payload as TrainingSession).workoutId);workoutId.value=workouts.value[(i+1)%workouts.value.length]?.id||'';view.value='progressi';notify('Allenamento salvato. Un passo in più.');void sync()}
async function destroy(){const r=deleteRecord.value;if(!r)return;try{if(rows.value.some(x=>x.parent_id===r.id&&!x.deleted))throw new Error('Elimina prima gli elementi contenuti.');await saveRecord(owner.value,r.kind,r.payload,{id:r.id,deleted:true,expectedRevision:r.localRevision});deleteRecord.value=null;notify('Elemento eliminato. Lo storico delle sessioni resta intatto.');void sync()}catch(e){notify(String(e))}}
async function logout(){if(!local.value&&pending.value){notify('Sincronizza o risolvi i conflitti prima di uscire. Puoi esportare i dati.');return}if(syncing){notify('Attendi il termine della sincronizzazione.');return}const id=owner.value;if(auth.value&&authSession.value){const {error}=await auth.value.auth.signOut({scope:'local'});if(error){notify(error.message);return}await removeAccountCache(id)}local.value=false;localStorage.removeItem('gymbrain-local');logoutOpen.value=false;view.value='oggi'}
function exportData(){const blob=new Blob([JSON.stringify({format:'gymbrain-export-v1',exportedAt:new Date().toISOString(),records:rows.value},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='gymbrain-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function mediaRequest(endpoint:string,body:unknown){const {data}=await auth.value!.auth.getSession();if(!data.session)throw new Error('Accedi di nuovo');const response=await fetch('/api/media/'+endpoint,{method:'POST',headers:{Authorization:'Bearer '+data.session.access_token,'Content-Type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(75000)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Operazione non disponibile');return result}
async function uploadVideo(row:LocalRecord,event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(!auth.value||local.value||!online.value){notify('Collega un account e torna online per caricare video.');return}if(file.size>25*1024*1024||!['video/mp4','video/webm','video/quicktime'].includes(file.type)){notify('Scegli un video MP4, WebM o MOV fino a 25 MB.');return}busy.value=true;try{const id=owner.value,upload=await mediaRequest('upload-url',{type:file.type,size:file.size}),path=upload.path;const {error}=await auth.value.storage.from('exercise-videos').uploadToSignedUrl(path,upload.token,file,{contentType:file.type});if(error)throw error;await saveRecord(id,'exercise',{...row.payload as Exercise,videoPath:path},{id:row.id,expectedRevision:row.localRevision});notify('Video allegato.');void sync()}catch(e){notify(String(e))}finally{busy.value=false;(event.target as HTMLInputElement).value=''}}
async function playVideo(row:LocalRecord){const e=row.payload as Exercise;if(e.videoPath){if(!auth.value||!online.value){notify('Questo allegato richiede una connessione.');return}try{videoUrl.value=(await mediaRequest('download-url',{path:e.videoPath})).url}catch(error){notify(error instanceof Error?error.message:'Video non disponibile')}}else if(e.videoUrl){window.open(e.videoUrl,'_blank','noopener,noreferrer')}}
async function resolve(keep:boolean){if(!conflictRecord.value)return;await resolveConflict(owner.value,conflictRecord.value.id,keep);conflictRecord.value=null;void sync()}
const date=(value:string)=>new Date(value).toLocaleDateString('it-IT',{day:'numeric',month:'short',year:'numeric'})
</script>
<template><NuxtPwaManifest/><div class="ambient" aria-hidden="true"/><div v-if="!ready" class="loading-screen"><img src="/favicon.svg" alt="Gymbrain"/><p>Prepariamo il tuo spazio…</p></div><AuthPanel v-else-if="!owner||recovery" :client="auth" :allow-local="Boolean(cfg.public.allowLocalDemo)" :recovery="recovery" @local="enterLocal" @recovered="recovery=false"/><template v-else><aside class="sidebar"><a class="brand" href="#" @click.prevent="view='oggi'"><img src="/favicon.svg" alt="">gymbrain<span>®</span></a><div class="side-label">IL TUO SPAZIO</div><nav aria-label="Navigazione principale"><button v-for="n in [['oggi','Oggi','grid'],['percorso','Percorso','layers'],['esercizi','Esercizi','barbell'],['progressi','Progressi','chart'],['account','Account','info']]" :key="n[0]" :class="{active:view===n[0]}" :aria-current="view===n[0]?'page':undefined" @click="view=n[0]!;"><span><GIcon :name="n[2]!"/></span>{{ n[1] }}</button></nav><div class="side-bottom"><span class="demo-dot"/>{{ local?'Solo dispositivo':online?'Il tuo spazio personale':'Sei offline' }}<p>{{ local?'Dati locali, senza sincronizzazione':pending+ ' modifiche in attesa' }}</p><button class="profile profile-button" @click="view='account'"><span class="avatar">{{ displayName[0] }}</span><span>{{ displayName }}<small>Il tuo ritmo. Il tuo percorso.</small></span></button></div></aside><main><header><span>Il tuo spazio <i>/</i> {{ {oggi:'Oggi',percorso:'Percorso',esercizi:'Esercizi',progressi:'Progressi',account:'Account'}[view as 'oggi'] }}</span><button class="sync-chip" :class="{offline:!online}" @click="view='account'">{{ local?'Solo dispositivo':!online?'Offline':pending?pending+' da sincronizzare':'Il tuo spazio' }}<span class="avatar small">{{ displayName[0] }}</span></button></header><div v-if="conflicts.length" class="conflict-banner"><span>{{ conflicts.length }} modifiche richiedono la tua scelta.</span><button class="text-btn" @click="conflictRecord=conflicts[0]!">Risolvi →</button></div><div id="content"><Transition name="view" mode="out-in"><div :key="view">
<template v-if="view==='oggi'||view==='percorso'"><div class="intro"><div><span class="eyebrow">MENO DISTRAZIONI. PIÙ INTENZIONE.</span><h1 v-if="view==='oggi'">Ogni serie <em>conta.</em></h1><h1 v-else>Una direzione. <em>La tua.</em></h1><p>{{ view==='oggi'?`Bentornato, ${displayName}. Costruiamo il tuo prossimo livello.`:'Mesocicli, schede e giornate. Al tuo ritmo.' }}</p></div><div class="date">{{ new Date().toLocaleDateString('it-IT',{weekday:'long',day:'numeric',month:'long'}) }}<br>Il momento giusto è adesso.</div></div>
<section v-if="!cycles.length" class="hero empty-hero"><span class="eyebrow">IL TUO PRIMO PASSO</span><h2>Fai spazio<br>alla tua forza.</h2><p>Crea il tuo mesociclo o parti da una scheda modificabile.</p><div class="button-group"><button class="primary" :disabled="busy" @click="seed">{{ busy?'Creazione…':'Usa percorso iniziale' }} <GIcon name="arrow"/></button><button class="secondary" @click="openEditor('cycle')">Crea da zero +</button></div><div class="orb" aria-hidden="true"><i v-for="i in 6" :key="i"/></div></section>
<template v-else><div v-if="view==='percorso'" class="selection-bar"><label>Mesociclo<select v-model="cycleId" @change="planId='';workoutId=''"><option v-for="c in cycles" :key="c.id" :value="c.id">{{ (c.payload as any).name }}</option></select></label><button class="secondary" @click="openEditor('cycle')">Nuovo mesociclo +</button><button class="text-btn" @click="openEditor('cycle',cycle)">Modifica</button><button class="text-btn danger" @click="deleteRecord=cycle!">Elimina</button></div><div class="dashboard"><section class="hero"><span class="eyebrow">IL TUO MESOCICLO</span><h2>{{ (cycle!.payload as any).name }}</h2><p>{{ (cycle!.payload as any).notes||'Un allenamento alla volta.' }}</p><div class="orb" aria-hidden="true"><i v-for="i in 6" :key="i"/><div class="orb-center">{{ String(week).padStart(2,'0') }}<small>SETTIMANA</small></div></div><div class="hero-bottom"><div><span>SETTIMANA {{ week }} DI {{ (cycle!.payload as any).weeks }}</span><div class="week-track"><b v-for="i in Math.min((cycle!.payload as any).weeks,12)" :key="i" :class="{done:i<=week}"/></div></div><button v-if="view==='oggi'" class="text-btn" @click="view='percorso'">Esplora il percorso ↗</button><span v-else class="subtle">Dal {{ date((cycle!.payload as any).start) }}</span></div></section>
<section class="panel weight-panel"><div class="panel-title"><h2>Il tuo peso</h2><button class="icon-btn" aria-label="Registra peso" @click="openEditor('weight')">+</button></div><div class="weight">{{ latestWeight?latestWeight.kg.toLocaleString('it-IT'):'—' }}<small>kg</small></div><div class="subtle">Un dato. Non il tuo valore.</div><svg v-if="graph" class="sparkline" viewBox="0 0 280 75" role="img" aria-label="Andamento delle tue ultime pesate"><path :d="graph" fill="none" stroke="#a9c8d4" stroke-width="2"/></svg><div v-else class="graph-empty subtle">{{ latestWeight?'Registra un’altra pesata per vedere l’andamento.':'La tua prima pesata ti aspetta.' }}</div><div class="weight-bottom"><span>Registrazione manuale</span><span>{{ latestWeight?date(latestWeight.measuredAt):'Nessun dato' }}</span></div></section>
<section class="panel workout"><div class="workout-heading"><div><span class="eyebrow">{{ ongoing?'IL TUO ALLENAMENTO TI ASPETTA':'IL TUO PROSSIMO PASSO' }}</span><h2>{{ workoutData?.name||'Crea la tua giornata' }}</h2></div><span class="round-arrow" aria-hidden="true">↗</span></div><div class="plan-select"><label>Scheda<select :value="plan?.id" @change="planId=($event.target as HTMLSelectElement).value;workoutId=''"><option v-for="p in plans" :key="p.id" :value="p.id">{{ (p.payload as any).name }}</option></select></label><button v-if="view==='percorso'" class="text-btn" @click="openEditor('plan',undefined,cycle!.id)">Nuova +</button><button v-if="plan&&view==='percorso'" class="text-btn" @click="openEditor('plan',plan)">Modifica</button></div><p v-if="plan" class="subtle">{{ (plan.payload as any).notes }}</p><div class="days"><button v-for="(w,i) in workouts" :key="w.id" class="day" :class="{selected:w.id===workout?.id}" :aria-pressed="w.id===workout?.id" @click="workoutId=w.id"><strong>{{ String.fromCharCode(65+i) }} · {{ (w.payload as Workout).name }}</strong>{{ (w.payload as Workout).exercises.length }} esercizi</button></div><div v-if="workoutData"><div v-for="e in workoutData.exercises" :key="e.id" class="exercise-row"><div class="exercise-symbol"><GIcon :name="e.mode==='band'?'leaf':'barbell'"/></div><div class="exercise-info"><strong>{{ e.name }}</strong><small>{{ modeNames[e.mode] }}{{ e.band?' · '+e.band:'' }}</small><small v-if="e.notes">{{ e.notes }}</small></div><span>{{ e.sets.length }} × {{ e.sets.map(s=>s.reps??'—').filter((v,i,a)=>a.indexOf(v)===i).join('/') }}</span></div><div class="workout-action"><span class="subtle">{{ workoutData.exercises.length }} esercizi · {{ workoutData.exercises.reduce((n,e)=>n+e.sets.length,0) }} serie</span><button class="primary" @click="start">{{ ongoing?'Riprendi sessione':'Entra in allenamento' }} <GIcon name="arrow"/></button></div></div><p v-else class="notice">Aggiungi una scheda e le tue giornate per iniziare.</p><div v-if="view==='percorso'" class="button-group editor-actions"><button v-if="plan" class="text-btn" @click="openEditor('workout',undefined,plan!.id)">Nuova giornata +</button><button v-if="workout" class="text-btn" @click="openEditor('workout',workout)">Modifica giornata</button><button v-if="workout" class="text-btn danger" @click="deleteRecord=workout!">Elimina giornata</button><button v-if="plan&&!workouts.length" class="text-btn danger" @click="deleteRecord=plan!">Elimina scheda</button></div></section>
<div class="right-stack"><section class="panel"><div class="panel-title"><h2>Ritmo settimanale</h2><span>QUESTA SETTIMANA</span></div><div class="activity-number">{{ weekly.length }}<small> sessioni</small></div><div class="week-bars"><div v-for="(d,i) in ['L','M','M','G','V','S','D']" :key="i"><b :class="{filled:activity[i],today:(new Date().getDay()+6)%7===i}" :style="{animationDelay:i*60+'ms'}"/>{{ d }}</div></div><span class="subtle">{{ weekly.length?'La costanza sta prendendo forma.':'Il primo passo fa la differenza.' }}</span></section><div class="quote"><p>“Non serve essere pronti.<br>Serve esserci.”</p><span>UN ALLENAMENTO ALLA VOLTA.</span></div></div></div></template></template>
<template v-else-if="view==='esercizi'"><div class="intro"><div><span class="eyebrow">MOVIMENTI ESSENZIALI. POSSIBILITÀ INFINITE.</span><h1>Il tuo <em>repertorio.</em></h1><p>Le note generali restano qui. Quelle della scheda seguono il periodo.</p></div><button class="primary" @click="openEditor('exercise')">Nuovo esercizio <GIcon name="plus"/></button></div><input v-model="search" class="search" type="search" aria-label="Cerca esercizi" placeholder="Cerca un movimento…"><TransitionGroup name="list" tag="div" class="library"><article v-for="e in filteredCatalog" :key="e.id" class="panel exercise-card"><div class="inline-top"><div class="exercise-symbol"><GIcon name="barbell"/></div><button class="icon-btn" :aria-label="'Modifica '+(e.payload as Exercise).name" @click="openEditor('exercise',e)">✎</button></div><span class="eyebrow">{{ modeNames[(e.payload as Exercise).mode] }}</span><h2>{{ (e.payload as Exercise).name }}</h2><p class="subtle">{{ (e.payload as Exercise).description }}</p><p class="subtle">{{ (e.payload as Exercise).notes }}</p><div class="card-tools"><button v-if="(e.payload as Exercise).videoPath||(e.payload as Exercise).videoUrl" class="text-btn" @click="playVideo(e)">▷ Video</button><label class="text-btn upload-label">Allega video<input type="file" accept="video/mp4,video/webm,video/quicktime" :disabled="busy" @change="uploadVideo(e,$event)"></label><button class="text-btn danger" @click="deleteRecord=e">Elimina</button></div></article></TransitionGroup><p v-if="!filteredCatalog.length" class="empty">{{ search?'Nessun movimento corrisponde alla ricerca.':'Crea il primo esercizio del tuo catalogo.' }}</p></template>
<template v-else-if="view==='progressi'"><div class="intro"><div><span class="eyebrow">UN ALLENAMENTO ALLA VOLTA</span><h1>Il lavoro <em>si vede.</em></h1><p>{{ completed.length }} allenamenti completati. Ogni passo conta.</p></div><button class="secondary" @click="exportData">Esporta i tuoi dati ↗</button></div><section class="panel"><div class="panel-title"><h2>Il tuo diario</h2><span>{{ sessions.length }} sessioni</span></div><button v-for="s in sessions" :key="s.id" class="history-item history-button" @click="(s.payload as TrainingSession).completedAt?historyRecord=s:(sessionRecord=s,focusMode=true)"><span>{{ (s.payload as TrainingSession).name }}<small>{{ date((s.payload as TrainingSession).startedAt) }} · {{ (s.payload as TrainingSession).exercises.reduce((n,e)=>n+e.actual.filter(s=>s.done).length,0) }} serie · {{ (s.payload as TrainingSession).bodyWeight??'—' }} kg corporei</small></span><span class="text-lime">{{ (s.payload as TrainingSession).completedAt?'Dettagli ↗':'Riprendi →' }}</span></button><div v-if="!sessions.length" class="empty">Il tuo prossimo allenamento inizia qui.<br><button class="text-btn" @click="view='oggi'">Torna al tuo percorso →</button></div></section></template>
<template v-else><div class="intro"><div><span class="eyebrow">TUTTO SOTTO CONTROLLO</span><h1>Il tuo <em>spazio.</em></h1><p>{{ authSession?.user.email||'Modalità locale · dati su questo dispositivo' }}</p></div></div><div class="program-grid"><section class="panel"><h2>Salvataggio e sincronizzazione</h2><p class="subtle" role="status">{{ status }}</p><p>{{ pending }} modifiche {{ local?'locali':'in attesa' }} · {{ conflicts.length }} conflitti</p><p class="notice">Gli allenamenti vengono salvati prima sul dispositivo. Con un account, si sincronizzano all’apertura, ogni 30 secondi e al ritorno della connessione.</p><div class="button-group"><button v-if="!local" class="primary" @click="sync">Sincronizza ora <GIcon name="arrow"/></button><button class="secondary" @click="exportData">Esporta backup</button></div><button v-for="c in conflicts" :key="c.id" class="history-button history-item" @click="conflictRecord=c">{{ (c.payload as any).name||'Pesata' }} · risolvi →</button><p class="notice">Il backup JSON include schede, sessioni e dati locali. Conservalo in un luogo personale.</p><button class="text-btn" @click="logoutOpen=true">{{ local?'Torna all’accesso':'Esci da questo dispositivo' }} →</button></section><section class="panel"><h2>Gymbrain sempre con te</h2><p class="subtle">Su iPhone: apri questa app in Safari, tocca Condividi → Aggiungi alla schermata Home.</p><p class="subtle">Su Chrome: usa “Installa app” dal menu del browser, quando disponibile.</p><p class="notice">Apri l’app online almeno una volta prima di allenarti senza connessione. I video allegati richiedono la rete.</p><h3>Il peso, al tuo ritmo</h3><p class="subtle">L’inserimento manuale è attivo. Il collegamento Withings richiede la registrazione dell’integrazione: non è ancora connesso.</p><button class="secondary" @click="openEditor('weight')">Registra peso +</button></section></div></template>
</div></Transition></div><footer>MADE FOR YOUR NEXT LEVEL <span>GYMBRAIN · IL TUO RITMO</span></footer></main><RecordEditor :open="editor.open" :kind="editor.kind" :record="editor.record" :parent-id="editor.parentId" :catalog="catalog" @close="editor.open=false" @save="save"/><WorkoutSession :open="focusMode" :record="sessionRecord" :owner="owner" :catalog="catalog" @close="focusMode=false" @saved="sync" @completed="sessionComplete" @error="notify"/>
<AppModal :open="!!deleteRecord" title="ELIMINA ELEMENTO" @close="deleteRecord=null"><h2>Eliminare {{ (deleteRecord?.payload as any)?.name||'questo elemento' }}?</h2><p class="notice">Le sessioni già registrate conservano esercizi e prescrizioni originali. Mesocicli e schede devono essere svuotati prima di eliminarli.</p><button class="primary" @click="destroy">Conferma eliminazione</button></AppModal>
<AppModal :open="logoutOpen" title="IL TUO ACCOUNT" @close="logoutOpen=false"><h2>{{ local?'Tornare all’accesso?':'Uscire da questo dispositivo?' }}</h2><p class="notice">{{ local?'I dati locali rimangono in questo browser, separati dagli account.':'La cache di questo account verrà rimossa dopo la sincronizzazione. I dati online restano nel tuo account.' }}</p><p v-if="pending&&!local" class="error">Hai {{ pending }} modifiche non sincronizzate. Sincronizzale prima di uscire.</p><button class="primary" :disabled="!!pending&&!local" @click="logout">{{ local?'Torna all’accesso':'Esci e rimuovi cache' }}</button></AppModal>
<AppModal :open="!!historyRecord" title="OGNI SERIE HA UNA STORIA" wide @close="historyRecord=null"><template v-if="historyRecord"><h2>{{ (historyRecord.payload as TrainingSession).name }}</h2><p class="subtle">{{ date((historyRecord.payload as TrainingSession).startedAt) }} · {{ (historyRecord.payload as TrainingSession).bodyWeight??'—' }} kg corporei</p><section v-for="e in (historyRecord.payload as TrainingSession).exercises" :key="e.id" class="prescription-editor"><h3>{{ e.name }}</h3><p v-if="e.exerciseId!==e.originalExerciseId" class="badge">{{ e.originalName }} → {{ e.name }} · {{ e.substitutionReason }}</p><p class="subtle">{{ modeNames[e.mode] }} · {{ e.band }} · {{ e.notes }}</p><div v-for="(s,i) in e.actual" :key="i" class="history-set"><span>{{ i+1 }}. {{ s.done?'✓':'Non eseguita' }}</span><span>{{ s.reps??'—' }} rep</span><span>{{ s.load??'—' }} kg</span><span>RPE {{ s.rpe??'—' }}</span><span>RIR {{ s.rir??'—' }}</span><span>{{ s.tut??'—' }} s</span></div><p class="session-note">{{ e.sessionNotes }}</p></section></template></AppModal>
<AppModal :open="!!videoUrl" title="IL MOVIMENTO, DA VICINO" wide @close="videoUrl=''"><video v-if="videoUrl" :src="videoUrl" controls playsinline class="video-player"/></AppModal>
<AppModal :open="!!conflictRecord" title="DUE MODIFICHE, UNA SCELTA" wide @close="conflictRecord=null"><h2>Quale versione vuoi conservare?</h2><p class="notice">Un altro dispositivo ha modificato lo stesso elemento. Puoi esportare un backup prima di scegliere. Non uniamo i dati automaticamente.</p><div class="form-grid"><div><h3>Questo dispositivo</h3><pre class="conflict-data">{{ JSON.stringify(conflictRecord?.payload,null,2) }}</pre></div><div><h3>Versione online</h3><pre class="conflict-data">{{ JSON.stringify(conflictRecord?.conflict?.payload,null,2) }}</pre></div></div><div class="button-group"><button class="primary" @click="resolve(true)">Conserva locale</button><button class="secondary" @click="resolve(false)">Usa online</button><button class="text-btn" @click="exportData">Esporta backup</button></div></AppModal>
<div v-if="$pwa?.needRefresh" class="update-banner">Nuova versione pronta.<button class="text-btn" @click="$pwa.updateServiceWorker()">Aggiorna app</button></div></template><Transition name="toast"><div v-if="toast" id="toast" popover="manual" class="show" role="status">{{ toast }}</div></Transition></template>
